"""Character-prefix-aware bounded DataFrame column reordering."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    def __init__(self, df: pd.DataFrame = None):
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value):
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(a, b):
        if a == b:
            return len(a)
        lo, hi = 0, min(len(a), len(b))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _score(cls, strings):
        if len(strings) < 2:
            return 0
        strings = sorted(strings)
        total = 0
        previous = strings[0]
        for current in strings[1:]:
            total += cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _positions(columns):
        result = {}
        for i, name in enumerate(columns):
            result.setdefault(str(name), []).append(i)
        return result

    @classmethod
    def _blocks(cls, width, columns, requested):
        parent = list(range(width))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        positions = cls._positions(columns)
        for pair in requested or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                a, b = find(left[0]), find(right[0])
                if a != b:
                    parent[b] = a

        groups = {}
        for i in range(width):
            groups.setdefault(find(i), []).append(i)
        return sorted((sorted(x) for x in groups.values()), key=lambda x: x[0])

    @classmethod
    def _edges(cls, columns, dependencies, blocks):
        positions = cls._positions(columns)
        edges, seen = [], set()

        def add(a, b):
            if a != b and (a, b) not in seen:
                seen.add((a, b))
                edges.append((a, b))

        for pair in dependencies or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                add(left[0], right[0])

        for block in blocks:
            for left, right in zip(block, block[1:]):
                add(left, right)
        return edges

    @classmethod
    def _repair(cls, width, preference, columns, dependencies, blocks):
        outgoing = [[] for _ in range(width)]
        indegree = [0] * width
        for left, right in cls._edges(columns, dependencies, blocks):
            outgoing[left].append(right)
            indegree[right] += 1

        rank = {column: i for i, column in enumerate(preference)}
        heap = [(rank.get(i, width + i), i)
                for i in range(width) if indegree[i] == 0]
        heapq.heapify(heap)
        answer = []
        while heap:
            _, node = heapq.heappop(heap)
            answer.append(node)
            for nxt in outgoing[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(heap, (rank.get(nxt, width + nxt), nxt))
        return answer if len(answer) == width else list(preference)

    @classmethod
    def _statistics(cls, text):
        rows, width = text.shape
        repeat, prefix, total = [], [], []
        for col in range(width):
            values = list(text[:, col])
            counts = {}
            mass = 0
            for value in values:
                counts[value] = counts.get(value, 0) + 1
            for value, count in counts.items():
                mass += len(value) * count * (count - 1)
            ordered = sorted(values)
            pscore = 0
            for a, b in zip(ordered, ordered[1:]):
                pscore += cls._lcp(a, b)
            repeat.append(mass)
            prefix.append(pscore)
            total.append(sum(len(v) for v in values))
        return repeat, prefix, total

    @staticmethod
    def _affinity(text, left, right):
        groups = {}
        for row, value in enumerate(text[:, left]):
            groups.setdefault(value, []).append(row)
        result = 0
        for rows in groups.values():
            if len(rows) < 2:
                continue
            counts = {}
            for row in rows:
                value = text[row, right]
                counts[value] = counts.get(value, 0) + 1
            for value, count in counts.items():
                result += len(value) * count * (count - 1)
        return result

    @classmethod
    def _beam_preference(cls, text, repeat, blocks):
        if len(blocks) <= 1:
            return list(blocks[0]) if blocks else []

        mass = [sum(repeat[c] for c in block) for block in blocks]
        active = sorted(range(len(blocks)),
                        key=lambda i: (-mass[i], blocks[i][0]))[:24]
        if not active:
            return [c for block in blocks for c in block]

        affinity = {}
        for left in active:
            for right in active:
                if left == right:
                    continue
                value = 0
                for a in blocks[left][:2]:
                    for b in blocks[right][:2]:
                        value += cls._affinity(text, a, b)
                affinity[left, right] = value

        states = [((seed,), frozenset(active) - {seed}, 0) for seed in active]
        for _ in range(len(active) - 1):
            expanded = []
            for path, remaining, value in states:
                for nxt in remaining:
                    expanded.append((
                        path + (nxt,),
                        remaining - {nxt},
                        value + affinity.get((path[-1], nxt), 0),
                    ))
            if not expanded:
                break
            expanded.sort(key=lambda x: (-x[2], x[0]))
            states = expanded[:4]

        best = max(states, key=lambda x: (x[2], tuple(-z for z in x[0])))
        used = set(best[0])
        tail = sorted((i for i in range(len(blocks)) if i not in used),
                      key=lambda i: (-mass[i], blocks[i][0]))
        return [column for block_id in best[0] + tuple(tail)
                for column in blocks[block_id]]

    @staticmethod
    def _serialize(text, orders):
        return ["".join(text[row, col] for col in orders[row])
                for row in range(text.shape[0])]

    @staticmethod
    def _materialize(df, source, orders, serialized):
        row_order = sorted(range(len(orders)),
                           key=lambda row: (serialized[row], row))
        values = np.empty(source.shape, dtype=object)
        public_orders = []
        for output_row, source_row in enumerate(row_order):
            order = orders[source_row]
            values[output_row, :] = [source[source_row, col] for col in order]
            public_orders.append([df.columns[col] for col in order])
        return (
            pd.DataFrame(values, index=df.index.take(row_order),
                         columns=list(df.columns)),
            public_orders,
        )

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        rows, width = df.shape
        if rows == 0 or width == 0:
            result = df.copy()
            orders = [[] for _ in range(rows)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((rows, width), dtype=object)
        for col in range(width):
            text[:, col] = [self._cell_string(value)
                            for value in source[:, col]]

        columns = list(df.columns)
        blocks = self._blocks(width, columns, col_merge)
        repeat, prefix, total = self._statistics(text)

        equality_order = sorted(
            range(width),
            key=lambda c: (-repeat[c], -prefix[c], -total[c], c),
        )
        prefix_order = sorted(
            range(width),
            key=lambda c: (-prefix[c], -repeat[c], -total[c], c),
        )
        beam_order = self._beam_preference(text, repeat, blocks)

        preferences = [equality_order, prefix_order, beam_order]
        seen = set()
        best_score, best_orders, best_serialized = -1, None, None

        for preference in preferences:
            repaired = self._repair(
                width, preference, columns, one_way_dep, blocks
            )
            marker = tuple(repaired)
            if marker in seen:
                continue
            seen.add(marker)
            orders = [repaired[:] for _ in range(rows)]
            serialized = self._serialize(text, orders)
            score = self._score(serialized)
            if score > best_score:
                best_score = score
                best_orders = orders
                best_serialized = serialized

        result, public_orders = self._materialize(
            df, source, best_orders, best_serialized
        )
        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")
        self._last_orders = public_orders
        return result, public_orders

